import{_ as l,l as o,o as e,c as n,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"对准标记设计","description":"","frontmatter":{"title":"对准标记设计","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/alignment-mark-design.md","filePath":"litho/alignment-mark-design.md","lastUpdated":1789023840000}'),E={name:"litho/alignment-mark-design.md"};function m(_,a,c,A,P,u){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="对准标记设计" tabindex="-1">对准标记设计 <a class="header-anchor" href="#对准标记设计" aria-label="Permalink to &quot;对准标记设计&quot;">​</a></h1><div class="epigraph"><p>标记要在薄膜和 CMP 之后仍可被传感器看见，又不能抢太多硅面积。周期、占空比和分层是设计，不是装饰。</p><footer>—— 对照 [套刻标记](/litho/overlay-marks)；对准与套刻标记常近邻但合同不同</footer></div><p><a href="/litho/alignment-sensors">上一课</a>给出读头。缺口是晶圆上印什么给它读。本课钉对准标记设计，不把高阶套刻模型提前写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>细密器件节距的标记对比弱；太大的标记浪费边缘。CMP 会把沟槽填偏，造成对准偏置。与套刻标记（成像或衍射套刻）若共用同一结构，优化目标冲突：对准要捕获鲁棒，套刻要残差可分解。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>周期匹配传感器波长与阶次；分段、双重图形层要标明「对哪一次曝光」。工艺窗口：在刻蚀/CMP 后抽检标记不对称。设计规则进 PDK，不是 OPC 临时加。</p>',7)),(e(),s(p,null,{default:r(()=>[h(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20DR%5B%22%E6%A0%87%E8%AE%B0%E8%AE%BE%E8%AE%A1%E8%A7%84%E5%88%99%22%5D%20--%3E%20PRINT%5B%22%E9%9A%8F%E5%B1%82%E5%8D%B0%E5%88%B7%22%5D%0A%20%20PRINT%20--%3E%20PROC%5B%22%E8%96%84%E8%86%9C%20%2F%20CMP%22%5D%0A%20%20PROC%20--%3E%20SNS%5B%22%E4%BC%A0%E6%84%9F%E5%99%A8%E8%AF%BB%E6%95%B0%22%5D%0A%20%20SNS%20--%3E%20BIAS%5B%22%E4%B8%8D%E5%AF%B9%E7%A7%B0%E5%81%8F%E7%BD%AE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">零层（zero layer）标记在有源区前，后续层都对它。损了要靠冗余或后层标记接力，这是策略课的网格，本课只谈单颗几何。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>衍射效率随占空比和深度；CMP 改变有效占空比 → 位置偏。多波长通道对同一几何权重不同，设计要让各色都还有信号。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课减振：标记再好，地板在抖也套不准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>标记几何是对准偏置的源头之一，要按层、按工艺设计。</li><li>对准标记与套刻标记合同分开。</li><li>出处：套刻标记课；对准传感器课。</li></ul>',7))])}const T=l(E,[["render",m]]);export{f as __pageData,T as default};
